```js
export function* unifiedDiff(a, b, n = 3) {
  const sm = new SequenceMatcher(a, b);
  let started = false;
  for (const group of sm.getGroupedOpcodes(n)) {
    if (!started) {
      started = true;
      yield '--- ';
      yield '+++ ';
    }
    const first = group[0], last = group[group.length - 1];
    yield `@@ -${formatRangeUnified(first[1], last[2])} +${formatRangeUnified(first[3], last[4])} @@`;
    for (const [tag, i1, i2, j1, j2] of group) {
      if (tag === 'equal') {
        for (let i = i1; i < i2; i++) yield ' ' + a[i];
        continue;
      }
      if (tag === 'replace' || tag === 'delete') for (let i = i1; i < i2; i++) yield '-' + a[i];
      if (tag === 'replace' || tag === 'insert') for (let j = j1; j < j2; j++) yield '+' + b[j];
    }
  }
}
```

formatRangeUnified(start, stop): beginning = start+1; length = stop-start; if length===1 return String(beginning); if (!length) beginning--; return `${beginning},${length}`.

