/**
 * pystr.mjs
 * Faithful ports of the CPython `str` behaviors needed by this project:
 *   - str.splitlines()          -> splitlines()
 *   - repr(str)                 -> strRepr()
 *   - repr() of nested dicts    -> pyRepr()
 *
 * No external dependencies; only built-in JavaScript is used.
 */

// Characters Python's str.splitlines() treats as line boundaries.
// (Code units suffice: every boundary is in the BMP.)
const LINE_BOUNDARIES = new Set([
  '\n', // U+000A LINE FEED
  '\r', // U+000D CARRIAGE RETURN (\r\n counts as ONE boundary)
  '\x0b', // U+000B LINE TABULATION
  '\x0c', // U+000C FORM FEED
  '\x1c', // U+001C FILE SEPARATOR
  '\x1d', // U+001D GROUP SEPARATOR
  '\x1e', // U+001E RECORD SEPARATOR
  '\x85', // U+0085 NEXT LINE
  '\u2028', // U+2028 LINE SEPARATOR
  '\u2029', // U+2029 PARAGRAPH SEPARATOR
]);

/**
 * Port of CPython str.splitlines() (keepends=False).
 */
export function splitlines(s) {
  const lines = [];
  let cur = '';
  let i = 0;
  const n = s.length;
  while (i < n) {
    const ch = s[i];
    if (ch === '\r') {
      lines.push(cur);
      cur = '';
      // "\r\n" is a single line boundary
      i += i + 1 < n && s[i + 1] === '\n' ? 2 : 1;
    } else if (LINE_BOUNDARIES.has(ch)) {
      lines.push(cur);
      cur = '';
      i += 1;
    } else {
      cur += ch;
      i += 1;
    }
  }
  if (cur.length > 0) lines.push(cur);
  return lines;
}

// Python's str.isprintable(): a character is NOT printable when its Unicode
// general category is in group C (Cc, Cf, Cs, Co, Cn) or Z (Zs, Zl, Zp),
// with the single exception of U+0020 SPACE.
const NON_PRINTABLE = /[\p{C}\p{Z}]/u;

function isPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

/**
 * Port of CPython repr() for str.
 * Quote selection: single quotes, unless the string contains a single quote
 * and no double quote, in which case double quotes are used.
 */
export function strRepr(s) {
  let quote = "'";
  if (s.includes("'") && !s.includes('"')) quote = '"';
  let out = quote;
  for (const ch of s) { // iterates by Unicode code point
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (isPrintable(cp)) {
      out += ch;
    } else if (cp < 0x100) {
      out += '\\x' + cp.toString(16).padStart(2, '0');
    } else if (cp < 0x10000) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      out += '\\U' + cp.toString(16).padStart(8, '0');
    }
  }
  return out + quote;
}

/**
 * repr() for the restricted value model used here: strings and ordered
 * dictionaries (Map with string keys). Renders exactly like CPython's
 * dict repr: {'key1': value1, 'key2': value2} and {} when empty.
 */
export function pyRepr(value) {
  if (typeof value === 'string') return strRepr(value);
  if (value instanceof Map) {
    const parts = [];
    for (const [k, v] of value) parts.push(strRepr(k) + ': ' + pyRepr(v));
    return '{' + parts.join(', ') + '}';
  }
  throw new TypeError(`pyRepr: unsupported value type: ${typeof value}`);
}

/**
 * sequencematcher.mjs
 * Faithful port of CPython's difflib.SequenceMatcher, restricted to what
 * difflib.unified_diff needs: isjunk is always None, so the "junk" set is
 * always empty; the "popular"/autojunk heuristic (for sequences with
 * >= 200 elements) is reproduced exactly.
 *
 * Sequences are plain JS arrays of strings; elements are compared by value,
 * which matches Python's str element comparison for lists of str.
 */

export class SequenceMatcher {
  constructor(a, b, autojunk = true) {
    this.a = a;
    this.b = b;
    this.autojunk = autojunk;
    this.matchingBlocksCache = null;
    this.opcodesCache = null;
    this._chainB();
  }

  _chainB() {
    const b = this.b;
    // b2j: Map<element, number[]> with indices appended in ascending order,
    // exactly like Python's b2j.setdefault(elt, []).append(i).
    const b2j = (this.b2j = new Map());
    for (let i = 0; i < b.length; i++) {
      const elt = b[i];
      let indices = b2j.get(elt);
      if (indices === undefined) {
        indices = [];
        b2j.set(elt, indices);
      }
      indices.push(i);
    }

    // isjunk is None for unified_diff, so the junk set stays empty.
    this.bjunk = new Set();

    // Autojunk heuristic: for b of length >= 200, elements occurring more
    // than n // 100 + 1 times are treated as "popular" and removed from b2j.
    this.bpopular = new Set();
    const n = b.length;
    if (this.autojunk && n >= 200) {
      const ntest = Math.floor(n / 100) + 1;
      for (const [elt, indices] of b2j) {
        if (indices.length > ntest) this.bpopular.add(elt);
      }
      for (const elt of this.bpopular) b2j.delete(elt);
    }
  }

  findLongestMatch(alo = 0, ahi = null, blo = 0, bhi = null) {
    const a = this.a;
    const b = this.b;
    const b2j = this.b2j;
    const isbjunk = (x) => this.bjunk.has(x);
    if (ahi === null) ahi = a.length;
    if (bhi === null) bhi = b.length;
    let besti = alo;
    let bestj = blo;
    let bestsize = 0;

    let j2len = new Map();
    const nothing = [];
    for (let i = alo; i < ahi; i++) {
      const newj2len = new Map();
      const jdict = b2j.has(a[i]) ? b2j.get(a[i]) : nothing;
      for (const j of jdict) {
        if (j < blo) continue;
        if (j >= bhi) break;
        const k = (j2len.has(j - 1) ? j2len.get(j - 1) : 0) + 1;
        newj2len.set(j, k);
        if (k > bestsize) {
          besti = i - k + 1;
          bestj = j - k + 1;
          bestsize = k;
        }
      }
      j2len = newj2len;
    }

    // Extend the best match by non-junk elements on each end.
    while (
      besti > alo &&
      bestj > blo &&
      !isbjunk(b[bestj - 1]) &&
      a[besti - 1] === b[bestj - 1]
    ) {
      besti -= 1;
      bestj -= 1;
      bestsize += 1;
    }
    while (
      besti + bestsize < ahi &&
      bestj + bestsize < bhi &&
      !isbjunk(b[bestj + bestsize]) &&
      a[besti + bestsize] === b[bestj + bestsize]
    ) {
      bestsize += 1;
    }

    // Then extend by junk elements (no-op here since junk is always empty,
    // kept for exact parity with CPython).
    while (
      besti > alo &&
      bestj > blo &&
      isbjunk(b[bestj - 1]) &&
      a[besti - 1] === b[bestj - 1]
    ) {
      besti -= 1;
      bestj -= 1;
      bestsize += 1;
    }
    while (
      besti + bestsize < ahi &&
      bestj + bestsize < bhi &&
      isbjunk(b[bestj + bestsize]) &&
      a[besti + bestsize] === b[bestj + bestsize]
    ) {
      bestsize += 1;
    }

    return [besti, bestj, bestsize];
  }

  getMatchingBlocks() {
    if (this.matchingBlocksCache !== null) return this.matchingBlocksCache;
    const la = this.a.length;
    const lb = this.b.length;

    // Stack-based queue, popped from the end, exactly like CPython.
    const queue = [[0, la, 0, lb]];
    const matchingBlocks = [];
    while (queue.length > 0) {
      const [alo, ahi, blo, bhi] = queue.pop();
      const x = this.findLongestMatch(alo, ahi, blo, bhi);
      const [i, j, k] = x;
      if (k) {
        matchingBlocks.push(x);
        if (alo < i && blo < j) queue.push([alo, i, blo, j]);
        if (i + k < ahi && j + k < bhi) queue.push([i + k, ahi, j + k, bhi]);
      }
    }

    // Python's list.sort() on (i, j, k) tuples: stable, lexicographic.
    matchingBlocks.sort((u, v) => u[0] - v[0] || u[1] - v[1] || u[2] - v[2]);

    let i1 = 0;
    let j1 = 0;
    let k1 = 0;
    const nonAdjacent = [];
    for (const [ai, bj, size] of matchingBlocks) {
      if (i1 + k1 === ai && j1 + k1 === bj) {
        k1 += size;
      } else {
        if (k1) nonAdjacent.push([i1, j1, k1]);
        i1 = ai;
        j1 = bj;
        k1 = size;
      }
    }
    if (k1) nonAdjacent.push([i1, j1, k1]);
    nonAdjacent.push([la, lb, 0]);

    this.matchingBlocksCache = nonAdjacent;
    return nonAdjacent;
  }

  getOpcodes() {
    if (this.opcodesCache !== null) return this.opcodesCache;
    let i = 0;
    let j = 0;
    const answer = [];
    for (const [ai, bj, size] of this.getMatchingBlocks()) {
      let tag = '';
      if (i < ai && j < bj) tag = 'replace';
      else if (i < ai) tag = 'delete';
      else if (j < bj) tag = 'insert';
      if (tag) answer.push([tag, i, ai, j, bj]);
      i = ai + size;
      j = bj + size;
      if (size) answer.push(['equal', ai, i, bj, j]);
    }
    this.opcodesCache = answer;
    return answer;
  }

  *getGroupedOpcodes(n = 3) {
    let codes = this.getOpcodes();
    if (codes.length === 0) codes = [['equal', 0, 1, 0, 1]];

    // Fixup leading and trailing groups if they show no changes.
    if (codes[0][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = codes[0];
      codes[0] = [tag, Math.max(i1, i2 - n), i2, Math.max(j1, j2 - n), j2];
    }
    if (codes[codes.length - 1][0] === 'equal') {
      const [tag, i1, i2, j1, j2] = codes[codes.length - 1];
      codes[codes.length - 1] = [tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)];
    }

    const nn = n + n;
    let group = [];
    for (let [tag, i1, i2, j1, j2] of codes) {
      if (tag === 'equal' && i2 - i1 > nn) {
        group.push([tag, i1, Math.min(i2, i1 + n), j1, Math.min(j2, j1 + n)]);
        yield group;
        group = [];
        i1 = Math.max(i1, i2 - n);
        j1 = Math.max(j1, j2 - n);
      }
      group.push([tag, i1, i2, j1, j2]);
    }
    if (group.length > 0 && !(group.length === 1 && group[0][0] === 'equal')) {
      yield group;
    }
  }
}

/**
 * difflib.mjs
 * Faithful port of CPython's difflib.unified_diff as invoked by deepdiff:
 *   difflib.unified_diff(a_lines, b_lines, lineterm='')
 * i.e. fromfile/tofile/fromfiledate/tofiledate are all '' and n = 3.
 * With lineterm='', yielded items carry no trailing newline; callers join
 * them with '\n'.
 */

import { SequenceMatcher } from './sequencematcher.mjs';

// Port of difflib._format_range_unified.
function formatRangeUnified(start, stop) {
  let beginning = start + 1; // 1-based, like Python
  const length = stop - start;
  if (length === 1) return `${beginning}`;
  if (length === 0) beginning -= 1; // empty ranges begin at line just before
  return `${beginning},${length}`;
}

/**
 * Generator port of difflib.unified_diff(a, b, lineterm='').
 * a and b are arrays of strings (already split into lines).
 */
export function* unifiedDiff(a, b, n = 3) {
  const matcher = new SequenceMatcher(a, b);
  let started = false;
  for (const group of matcher.getGroupedOpcodes(n)) {
    if (!started) {
      started = true;
      // '--- {}{}{}'.format('', '', '') and '+++ {}{}{}'.format('', '', '')
      yield '--- ';
      yield '+++ ';
    }
    const first = group[0];
    const last = group[group.length - 1];
    const file1Range = formatRangeUnified(first[1], last[2]);
    const file2Range = formatRangeUnified(first[3], last[4]);
    yield `@@ -${file1Range} +${file2Range} @@`;

    for (const [tag, i1, i2, j1, j2] of group) {
      if (tag === 'equal') {
        for (let i = i1; i < i2; i++) yield ' ' + a[i];
        continue;
      }
      if (tag === 'replace' || tag === 'delete') {
        for (let i = i1; i < i2; i++) yield '-' + a[i];
      }
      if (tag === 'replace' || tag === 'insert') {
        for (let j = j1; j < j2; j++) yield '+' + b[j];
      }
    }
  }
}

/**
 * Convenience wrapper: the joined unified diff string exactly as deepdiff
 * stores it ('\n'.join(unified_diff(...))). Returns '' when there are no
 * line-level changes.
 */
export function unifiedDiffText(aLines, bLines, n = 3) {
  return [...unifiedDiff(aLines, bLines, n)].join('\n');
}

/**
 * deepdiff.mjs
 * Black-box reimplementation of the observable behavior of
 * deepdiff.DeepDiff(t1, t2) for the case where both t1 and t2 are strings
 * (which is all this program can produce, since argparse reads them as str).
 *
 * Observed contract (verified against the reference behavior):
 *   - t1 == t2                     -> {} (empty result)
 *   - t1 != t2                     -> {'values_changed': {'root':
 *                                       {'new_value': t2, 'old_value': t1}}}
 *   - additionally, when at least one of the strings contains '\n', a
 *     unified diff over str.splitlines() of both sides is computed; if it
 *     is non-empty it is stored under the 'diff' key (after 'old_value').
 *
 * The result is an ordered Map tree so that pyRepr() renders it with
 * Python's dict repr, key order and str repr semantics.
 */

import { splitlines } from './pystr.mjs';
import { unifiedDiffText } from './difflib.mjs';

/**
 * Returns a Map tree representing the DeepDiff result for two strings.
 */
export function deepDiffStrings(t1, t2) {
  const result = new Map();
  if (t1 === t2) return result;

  const root = new Map();
  root.set('new_value', t2);
  root.set('old_value', t1);

  if (t1.includes('\n') || t2.includes('\n')) {
    const diff = unifiedDiffText(splitlines(t1), splitlines(t2));
    if (diff.length > 0) root.set('diff', diff);
  }

  result.set('values_changed', new Map([['root', root]]));
  return result;
}

/**
 * argparse.mjs
 * Black-box reimplementation of the argparse behavior of:
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=str, required=True)
 *   parser.add_argument('--b', type=str, required=True)
 *   args = parser.parse_args()
 *
 * Reproduced semantics (verified against the reference behavior):
 *   - `--a VALUE` and `--a=VALUE` forms; unambiguous long-option prefixes
 *     (argparse's allow_abbrev), e.g. `--he` -> `--help`;
 *   - the token following an option is its value unless it "looks like an
 *     option string" (starts with '-', except '-', negative numbers like
 *     -5 / -1.5, and tokens containing a space);
 *   - `-h` / `--help` print help to stdout and exit 0;
 *   - a repeated option keeps the last value;
 *   - `--` stops option parsing; remaining tokens become extras;
 *   - missing required options: error listing them in definition order
 *     (checked BEFORE unrecognized arguments), exit code 2;
 *   - unknown options / stray positionals: `unrecognized arguments: ...`,
 *     exit code 2;
 *   - prog name is basename(argv[1]), like argparse's basename(sys.argv[0]).
 *
 * Only Node.js built-ins are used.
 */

import { basename } from 'node:path';

const LONG_OPTIONS = ['--help', '--a', '--b'];

// argparse._negative_number_matcher; with no number-like options registered,
// tokens matching this are treated as values, not option strings.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOptionString(token) {
  if (!token.startsWith('-')) return false;
  if (token === '-') return false; // a bare '-' is a value
  if (NEGATIVE_NUMBER.test(token)) return false;
  if (token.includes(' ')) return false; // tokens with spaces are values
  return true;
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function printHelpAndExit(prog) {
  const text =
    usageLine(prog) +
    '\n' +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n';
  process.stdout.write(text);
  process.exit(0);
}

function errorAndExit(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

/**
 * Parses argv (typically process.argv.slice(2)) and returns { a, b }.
 * Exits the process with argparse-compatible output on -h/error.
 */
export function parseArgs(argv, prog = basename(process.argv[1] || '')) {
  const values = { a: undefined, b: undefined };
  const seen = new Set();
  const extras = [];
  let optionsEnded = false;

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (optionsEnded) {
      extras.push(token);
      i += 1;
      continue;
    }
    if (token === '--') {
      optionsEnded = true;
      i += 1;
      continue;
    }
    if (token === '-h') {
      printHelpAndExit(prog);
    }
    if (token.startsWith('--')) {
      let name = token;
      let explicitValue;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        explicitValue = token.slice(eq + 1);
      }

      let resolved = null;
      if (LONG_OPTIONS.includes(name)) {
        resolved = name;
      } else {
        const matches = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
        if (matches.length === 1) {
          resolved = matches[0];
        } else if (matches.length > 1) {
          errorAndExit(prog, `ambiguous option: ${name} could match ${matches.join(', ')}`);
        }
      }

      if (resolved === null) {
        // Unknown long option: collected, reported at the end.
        extras.push(token);
        i += 1;
        continue;
      }
      if (resolved === '--help') {
        printHelpAndExit(prog);
      }

      const key = resolved.slice(2); // '--a' -> 'a'
      if (explicitValue !== undefined) {
        values[key] = explicitValue;
        seen.add(key);
        i += 1;
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || looksLikeOptionString(next)) {
        errorAndExit(prog, `argument ${resolved}: expected one argument`);
      }
      values[key] = next;
      seen.add(key);
      i += 2;
      continue;
    }
    if (looksLikeOptionString(token)) {
      // Unknown short option (e.g. '-x'): collected as an extra.
      extras.push(token);
      i += 1;
      continue;
    }
    // Plain value with no positional defined: extra.
    extras.push(token);
    i += 1;
  }

  // argparse checks required arguments before reporting unrecognized ones.
  const missing = [];
  if (!seen.has('a')) missing.push('--a');
  if (!seen.has('b')) missing.push('--b');
  if (missing.length > 0) {
    errorAndExit(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    errorAndExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test1_executable';
const JS = '/output/test1.mjs';

function run(cmd, args) {
  try {
    const out = execFileSync(cmd[0], [...cmd.slice(1), ...args], { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
    return { code: 0, out };
  } catch (e) {
    return { code: e.status, out: (e.stdout ?? '') + '\x00STDERR\x00' + (e.stderr ?? '') };
  }
}

function check(a, b, label) {
  const r1 = run([EXE], ['--a', a, '--b', b]);
  const r2 = run(['node', JS], ['--a', a, '--b', b]);
  if (r1.out !== r2.out || r1.code !== r2.code) {
    console.log(`MISMATCH [${label}]`);
    console.log('  a =', JSON.stringify(a).slice(0, 200));
    console.log('  b =', JSON.stringify(b).slice(0, 200));
    console.log('  py :', JSON.stringify(r1.out).slice(0, 400), 'code', r1.code);
    console.log('  js :', JSON.stringify(r2.out).slice(0, 400), 'code', r2.code);
    return false;
  }
  return true;
}

